  <a class="skip-link" href="#main">Skip to content</a>

  <header class="topbar">
    <div class="wrap nav" aria-label="Primary">
      <a class="brand" href="#">
        <span class="brand-mark" aria-hidden="true"></span>
        <span>Noir Cart</span>
      </a>
      <nav class="nav-links" aria-label="Main">
        <a href="#featured">Featured</a>
