  <script>
    const buttons = Array.from(document.querySelectorAll(".filter-btn"));
    const cards = Array.from(document.querySelectorAll(".product-card"));
    const search = document.getElementById("search");
    const year = document.getElementById("year");
    const timerNodes = Object.fromEntries(
      Array.from(document.querySelectorAll("[data-time]")).map((node) => [node.dataset.time, node])
    );

    let activeFilter = "all";
    let query = "";

    function normalize(value) {
      return value.trim().toLowerCase();
    }

    function applyFilters() {
      const text = normalize(query);
      cards.forEach((card) => {
        const matchesCategory = activeFilter === "all" || card.dataset.category === activeFilter;
        const matchesQuery = !text || card.textContent.toLowerCase().includes(text);
        card.classList.toggle("hidden", !(matchesCategory && matchesQuery));
      });
    }

    buttons.forEach((button) => {
      button.addEventListener("click", () => {
        activeFilter = button.dataset.filter;
        buttons.forEach((btn) => btn.setAttribute("aria-pressed", String(btn === button)));
        applyFilters();
      });
    });

    search?.addEventListener("input", (event) => {
      query = event.target.value;
      applyFilters();
    });

    document.querySelector(".newsletter-form")?.addEventListener("submit", (event) => {
      event.preventDefault();
    });

    year.textContent = new Date().getFullYear();

    const dealEnds = new Date(Date.now() + 2 * 24 * 60 * 60 * 1000 + 14 * 60 * 60 * 1000 + 36 * 60 * 1000 + 12 * 1000);
    function updateCountdown() {
      const remaining = Math.max(0, dealEnds - new Date());
      const days = Math.floor(remaining / 86400000);
      const hours = Math.floor((remaining % 86400000) / 3600000);
      const minutes = Math.floor((remaining % 3600000) / 60000);
      const seconds = Math.floor((remaining % 60000) / 1000);
      timerNodes.days.textContent = String(days).padStart(2, "0");
      timerNodes.hours.textContent = String(hours).padStart(2, "0");
      timerNodes.minutes.textContent = String(minutes).padStart(2, "0");
      timerNodes.seconds.textContent = String(seconds).padStart(2, "0");
    }

    updateCountdown();
    setInterval(updateCountdown, 1000);
  </script>
